"""Cache-budgeted IPv6 packed-image compiler (protocol 3)."""
import bisect
import json
import sys

import native
import solver
from protocol import Invalid, MAX_INPUT, parse_request

MAX_RUNS_PER_VERSION = 64
MAX_TOTAL_RUNS = 128


def _fib_versions(case):
    """Ordered immutable FIB versions, including the initial one."""
    routes = {}
    for route, hop in case["initial"]:
        routes[route] = hop
    versions = [solver.compile_atlas(((st, ln, hop) for (st, ln), hop in routes.items()))]
    for tx in case["transactions"]:
        for op, route, hop in tx:
            if op == "set":
                routes[route] = hop
            else:
                routes.pop(route, None)
        versions.append(
            solver.compile_atlas(((st, ln, hop) for (st, ln), hop in routes.items())))
    return versions


def compile_request(cases):
    result = {"cases": []}
    if not cases:
        return result
    payloads = []
    total_runs = 0
    for case in cases:
        versions = _fib_versions(case)
        for starts, _hops in versions:
            if len(starts) > MAX_RUNS_PER_VERSION:
                raise Invalid("version run bound")
            total_runs += len(starts)
        if total_runs > MAX_TOTAL_RUNS:
            raise Invalid("request run bound")
        per_version = [[] for _ in versions]
        for version, repeat, addresses in case["bursts"]:
            starts = versions[version][0]
            runs = [bisect.bisect_right(starts, addr) - 1 for addr in addresses]
            per_version[version].append((repeat, runs))
        payloads.append({
            "cache": case["cache_pages"],
            "hit": case["costs"][0],
            "miss": case["costs"][1],
            "decode": list(case["costs"][2]),
            "versions": versions,
            "bursts": [(version, repeat, runs)
                       for (version, repeat, addresses), (_, runs)
                       in zip(case["bursts"], [])] if False else
                       [(b[0], b[1], runs)
                        for b, runs in zip(case["bursts"],
                                           [[] for _ in case["bursts"]])],
        })
    # (runs are recomputed below; keep the payload construction explicit)
    for payload, case in zip(payloads, cases):
        payload["bursts"] = []
        for (version, repeat, addresses), runs in zip(case["bursts"],
                                                      payload_runs(payloads, case)):
            payload["bursts"].append((version, repeat, runs))
    layouts = native.solve(payloads)
    for case, payload, planned in zip(cases, payloads, layouts):
        versions = payload["versions"]
        out_versions = []
        layout_objects = []
        for (starts, hops), (image, nodes) in zip(versions, planned):
            out_versions.append({"starts": [format(x, "032x") for x in starts],
                                 "hops": list(hops), "image": image})
            layout_objects.append(solver.Layout(starts, hops, image, nodes))
        changes = []
        for index in range(len(versions) - 1):
            changes.append(solver.compute_changes(
                versions[index][0], versions[index][1],
                versions[index + 1][0], versions[index + 1][1]))
        bursts = []
        for version, repeat, addresses in case["bursts"]:
            runs = payload["runs_by_burst"][version] if False else None
        bursts = payload_bursts(case, payload)
        objective = solver.case_objective(
            layout_objects, payload["per_version"], case["costs"])
        result["cases"].append({"versions": out_versions, "changes": changes,
                                "bursts": bursts, "objective": objective})
    return result


def main():
    try:
        cases = parse_request(sys.stdin.buffer.read(MAX_INPUT + 1))
        result = compile_request(cases)
    except Invalid:
        result = {"error": "invalid"}
    json.dump(result, sys.stdout, separators=(",", ":"), allow_nan=False)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
